function ScenarioModeling() {
  const [scenarios, setScenarios] = React.useState([
    { id: 1, name: 'Base Case', description: 'Current business plan.' },
    { id: 2, name: 'Optimistic Growth', description: 'Increased sales and reduced costs.' },
  ]);

  const [newScenarioName, setNewScenarioName] = React.useState('');

  const handleCreateScenario = () => {
    // Dummy implementation
    const newScenario = { id: scenarios.length + 1, name: newScenarioName, description: 'New Scenario' };
    setScenarios([...scenarios, newScenario]);
    setNewScenarioName('');
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white shadow-md rounded-lg p-8 max-w-4xl w-full">
        <h1 className="text-2xl font-semibold text-gray-800 mb-4">Scenario Modeling</h1>
        <h2 className="text-xl font-semibold text-gray-700 mb-2">Existing Scenarios</h2>
        <ul>
          {scenarios.map((scenario) => (
            <li key={scenario.id} className="py-2 border-b border-gray-200">
              <span className="text-gray-600">{scenario.name} - {scenario.description}</span>
            </li>
          ))}
        </ul>
        <div className="mt-4">
          <label htmlFor="scenarioName" className="block text-gray-700 text-sm font-bold mb-2">New Scenario Name:</label>
          <input type="text" id="scenarioName" className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" value={newScenarioName} onChange={(e) => setNewScenarioName(e.target.value)} />
